import{notFound}from"next/navigation";import{RfqPrintDocument}from"@/components/procurement/rfq-print-document";import{db}from"@/lib/db";export const dynamic="force-dynamic";export default async function Page({params}:{params:Promise<{rfqId:string;supplierId:string}>}){const{rfqId,supplierId}=await params,[rfq,issuer,vendor]=await Promise.all([db.purchaseRfq.findFirst({where:{id:rfqId,deletedAt:null,vendors:{some:{supplierId}}},include:{sourceQuotation:true,sourceOrder:true,project:true,items:{orderBy:{sortOrder:"asc"}}}}),db.supplierProfile.findFirst({where:{isDefault:true,isActive:true,deletedAt:null}}),db.client.findFirst({where:{id:supplierId,clientType:{in:["SUPPLIER","BOTH"]},deletedAt:null,isActive:true}})]);if(!rfq||!vendor)notFound();return <RfqPrintDocument rfq={rfq} issuer={issuer} vendor={vendor}/>}
